		auto j = get_index<'j'>(state);

		v1[state] = (((num_t)j + (num_t)1) / fn) / (num_t)4.0;
		v2[state] = (((num_t)j + (num_t)1) / fn) / (num_t)6.0;
		y[state]  = (((num_t)j + (num_t)1) / fn) / (num_t)8.0;
