                   auto A, auto u1, auto v1, auto u2, auto v2,
                   auto w, auto x, auto y, auto z) {
	using namespace noarr;

	#pragma scop

	// ---------------------------------------------------------------------
	// 1) Rank-2 update:
	//    A[i][j] = A[i][j] + u1[i]*v1[j] + u2[i]*v2[j];
	//
	// Optimizations:
	//  - keep 'i' as outer dim and 'j' as inner for row-major locality
	//  - hoist u1[i] and u2[i] out of the inner j-loop
