		// trav_j.state() has just 'j' fixed
		auto sj = trav_j.state();
		const num_t y_j   = y[sj];
		const num_t scale = beta * y_j;

		// for this j, update all x[i] using the whole "column" A[j][i]
		trav_j.for_each([&](auto state) {
			// state has both 'i' and 'j'
			x[state] += scale * A_T[state];
		});
	});

	// ---------------------------------------------------------------------
	// 3) x[i] = x[i] + z[i];
	//
	// Simple elementwise vector addition.
	// ---------------------------------------------------------------------
	traverser(x, z).for_each([&](auto state) {
		x[state] += z[state];
