	// ---------------------------------------------------------------------
	// 4) w[i] = w[i] + alpha * A[i][j] * x[j];
	//
	// This is w += alpha * A * x.
	//
	// Optimizations:
	//  - create a view of x indexed by 'j' so x_j[j] == x[j]
	//  - for each row i, compute the dot-product sum_j A[i][j]*x[j] in a
	//    scalar accumulator:
	//        tmp = sum_j A[i][j] * x[j]
	//        w[i] += alpha * tmp;
	//    This:
	//      * improves cache behavior for w (one load+store per row)
	//      * reduces multiplications by alpha from O(N^2) to O(N)
	// ---------------------------------------------------------------------
	auto x_j = x ^ noarr::rename<'i', 'j'>();

