		// state with current row index i
		auto si = trav_i.state();

		num_t row_sum = (num_t)0;

		// inner loop over all columns j of row i
		trav_i.for_each([&](auto state) {
			// state has both 'i' and 'j'
			row_sum += A[state] * x_j[state];
		});

		// factor alpha outside the inner loop (one multiply per row)
		w[si] += alpha * row_sum;
	});

	#pragma endscop
