	// ------------------------------------------------------------------
	auto x_j = x ^ noarr::rename<'i', 'j'>();

	#pragma omp parallel for schedule(static)
	for (auto trav_i : traverser(A, w, x_j)) {
		auto s_i = trav_i.state(); // fixed index in 'i'

		// Start from the current value of w[i]
		num_t acc = w[s_i];

		// Inner loop over contiguous 'j' dimension of A
		trav_i.for_each([&](auto state) {
			acc += alpha * A[state] * x_j[state];
		});

		// Single store to w[i] after accumulating the whole row
